import * as T from 'three';
export function createCommanderControl({scene,camera,controls,renderer,commander,excluded,onEnter,onExit}){
 const root=commander.body.parent,keys=new Set(),boxes=[];let active=false,yaw=0,pitch=0,sprint=false,torch=false,joy={x:0,y:0},saved=null,clock=0;
 scene.updateMatrixWorld(true);
 scene.traverse(o=>{if(!o.isMesh||!o.geometry.attributes.position?.count||o.material?.transparent)return;for(let p=o;p;p=p.parent)if(excluded.includes(p)||p===root)return;if(o.userData.collisionBoxes){boxes.push(...o.userData.collisionBoxes.map(b=>b.clone()));return}const b=new T.Box3().setFromObject(o);if(Number.isFinite(b.max.x))boxes.push(b)});
 const lamp=new T.SpotLight('#fff1cc',22,22,.42,.6,1.5);lamp.visible=false;scene.add(lamp,lamp.target);
 const toggle=document.createElement('button');toggle.textContent='控制中隊長';document.querySelector('.viewcontrols').append(toggle);
 const hud=document.createElement('div');hud.className='commander-hud';hud.tabIndex=-1;hud.hidden=true;hud.innerHTML='<div class="fp-title">中隊長 · 第一人稱 <small>WASD 移動／拖曳轉頭／Shift 快走／F 照明／Esc 離開</small></div><div class="fp-cross">＋</div><div class="fp-stick" aria-label="移動搖桿"><span></span></div><div class="fp-actions"><button data-action="sprint">快走</button><button data-action="torch">照明</button><button data-action="home">回指揮點</button><button data-action="exit">退出視角</button></div><div class="fp-look">右側拖曳轉頭</div>';document.querySelector('.world').append(hud);
 const stick=hud.querySelector('.fp-stick'),thumb=stick.querySelector('span');let stickId=null,lookId=null,lookLast=null;
 const clear=()=>{keys.clear();joy={x:0,y:0};stickId=lookId=null;thumb.style.transform='translate(-50%,-50%)';};
 function leave(){if(!active)return;active=false;clear();commander.body.visible=true;hud.hidden=true;document.body.classList.remove('commander-mode');controls.enabled=true;camera.position.copy(saved.position);camera.quaternion.copy(saved.quaternion);controls.target.copy(saved.target);camera.fov=saved.fov;camera.updateProjectionMatrix();lamp.visible=false;toggle.textContent='控制中隊長';onExit?.();}
 toggle.onclick=()=>{if(active){leave();return}saved={position:camera.position.clone(),quaternion:camera.quaternion.clone(),target:controls.target.clone(),fov:camera.fov};onEnter();active=true;controls.enabled=false;commander.body.visible=false;hud.hidden=false;document.body.classList.add('commander-mode');yaw=root.rotation.y;pitch=0;camera.fov=70;camera.updateProjectionMatrix();toggle.textContent='退出角色控制';hud.focus({preventScroll:true});};
 function joystick(e){const r=stick.getBoundingClientRect(),x=(e.clientX-r.left-r.width/2)/45,y=(e.clientY-r.top-r.height/2)/45,l=Math.max(1,Math.hypot(x,y));joy={x:x/l,y:y/l};thumb.style.transform=`translate(calc(-50% + ${joy.x*36}px),calc(-50% + ${joy.y*36}px))`;}
 stick.onpointerdown=e=>{if(stickId!==null)return;stickId=e.pointerId;stick.setPointerCapture(e.pointerId);joystick(e);e.preventDefault()};stick.onpointermove=e=>{if(e.pointerId===stickId)joystick(e)};const stopStick=e=>{if(e.pointerId===stickId){stickId=null;joy={x:0,y:0};thumb.style.transform='translate(-50%,-50%)'}};stick.onpointerup=stopStick;stick.onpointercancel=stopStick;stick.onlostpointercapture=stopStick;
 hud.onpointerdown=e=>{hud.focus({preventScroll:true});if(e.target.closest('button,.fp-stick')||lookId!==null)return;lookId=e.pointerId;lookLast=[e.clientX,e.clientY];hud.setPointerCapture(e.pointerId);e.preventDefault()};hud.onpointermove=e=>{if(e.pointerId!==lookId)return;yaw-=(e.clientX-lookLast[0])*.004;pitch=T.MathUtils.clamp(pitch-(e.clientY-lookLast[1])*.004,-1.3,1.3);lookLast=[e.clientX,e.clientY]};hud.onpointerup=hud.onpointercancel=e=>{if(e.pointerId===lookId)lookId=null};
 function action(name){if(name==='exit')leave();if(name==='home'){root.position.set(-17,.175,5.6);yaw=0;pitch=0;clear()}if(name==='sprint'){sprint=!sprint;hud.querySelector('[data-action=sprint]').classList.toggle('active',sprint)}if(name==='torch'){torch=!torch;hud.querySelector('[data-action=torch]').classList.toggle('active',torch)}}hud.querySelectorAll('button').forEach(b=>b.onclick=()=>action(b.dataset.action));
 window.addEventListener('keydown',e=>{if(!active||e.target?.closest?.('input,select,textarea'))return;if(['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','ShiftLeft','ShiftRight'].includes(e.code)){keys.add(e.code);e.preventDefault()}if(e.code==='Escape')leave();if(e.code==='KeyF'&&!e.repeat)action('torch')});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',clear);document.addEventListener('visibilitychange',()=>{if(document.hidden)clear()});
 function ground(x,z,y){let top=-.15;for(const b of boxes)if(x>b.min.x-.015&&x<b.max.x+.015&&z>b.min.z-.015&&z<b.max.z+.015&&b.max.y<=y+.24&&b.max.y>top)top=b.max.y;return top;}
 function allowed(x,z,y){if(Math.abs(x)>44||z< -25||z>30)return false;return !boxes.some(b=>b.max.y>y+.3&&b.min.y<y+1.55&&x+.24>b.min.x&&x-.24<b.max.x&&z+.24>b.min.z&&z-.24<b.max.z)}
 function update(dt){if(!active)return;clock+=dt;let x=joy.x+(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0),z=joy.y+(keys.has('KeyS')||keys.has('ArrowDown')?1:0)-(keys.has('KeyW')||keys.has('ArrowUp')?1:0),len=Math.max(1,Math.hypot(x,z));x/=len;z/=len;const speed=sprint||keys.has('ShiftLeft')||keys.has('ShiftRight')?3.5:1.8,dx=(x*Math.cos(yaw)+z*Math.sin(yaw))*speed*dt,dz=(-x*Math.sin(yaw)+z*Math.cos(yaw))*speed*dt,steps=Math.max(1,Math.ceil(Math.hypot(dx,dz)/.1));
 for(let i=0;i<steps;i++){let p=root.position;const move=(x,z)=>{const nextGround=ground(x,z,p.y);if(nextGround<p.y-.45)return;if(allowed(x,z,nextGround)){p.x=x;p.z=z;p.y=nextGround}};move(p.x+dx/steps,p.z);move(p.x,p.z+dz/steps)}root.rotation.y=yaw;
 commander.body.position.y=0;commander.body.updateWorldMatrix(true,true);const bottom=Math.min(...commander.boots.map(b=>new T.Box3().setFromObject(b).min.y));commander.body.position.y+=root.position.y-bottom;
 camera.position.copy(root.position).add(new T.Vector3(0,1.62,0));camera.rotation.set(pitch,yaw,0,'YXZ');lamp.visible=torch;lamp.position.copy(camera.position);lamp.target.position.copy(camera.position).add(new T.Vector3(0,0,-1).applyQuaternion(camera.quaternion).multiplyScalar(10));}
 return {update,leave,get active(){return active},boxes,allowed,ground};
}
